/* Abo alerts core. createAlert(stage, opts) builds one alert and returns
   { el, duration, render(ms) }. Everything on screen is a pure function of the
   time passed to render(), so the preview loop, the headless recording and
   StreamElements all play the exact same frames. */
(function(global){
'use strict';
const DUR = 6000;
const clamp=(x,a,b)=>Math.min(b,Math.max(a,x));
const seg=(t,a,b)=>clamp((t-a)/(b-a),0,1);
const outExpo=p=>p>=1?1:1-Math.pow(2,-10*p);
const outCubic=p=>1-Math.pow(1-p,3);
const inCubic=p=>p*p*p;
const inOut=p=>p<.5?4*p*p*p:1-Math.pow(-2*p+2,3)/2;
const outBack=p=>{const c1=1.5,c3=c1+1;return 1+c3*Math.pow(p-1,3)+c1*Math.pow(p-1,2)};
const rnd=n=>{const x=Math.sin(n*12.9898+78.233)*43758.5453;return x-Math.floor(x)};
const GLYPHS='ABCDEFGHJKLMNPRSTUVWXYZ0123456789#/';
const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));

const CHEV='<svg viewBox="0 0 22 9"><path d="M0 0 L11 6 L22 0 L22 3 L11 9 L0 3 Z" fill="#E8B12B"/></svg>';

function tierInfo(raw){
  const s=String(raw||'').trim().toLowerCase();
  if(s.includes('prime')) return {n:1,label:'PRIME'};
  let n=parseInt(s,10);
  if(n>=1000) n=Math.round(n/1000);
  if(!(n>=1&&n<=3)) n=1;
  return {n,label:'TIER '+n};
}

function createAlert(stage, o){
  const T=Object.assign({
    followLabel:'New recruit', followLine:'has reported for duty.',
    subLabelNew:'Enlisted', subLabelRe:'Re-enlisted',
    subLineNew:'Signed on. Paperwork filed.', subLineRe:'Back for another tour.'
  }, o.text||{});
  const isSub=o.type==='sub';
  const months=Math.max(1,parseInt(o.months,10)||1);
  const resub=isSub&&months>1;
  const tier=tierInfo(o.tier);
  const name=String(o.name||'').trim()||'Unknown';

  const el=document.createElement('div');
  el.className='al '+(isSub?'sub':'follow');
  const label=isSub?(resub?T.subLabelRe:T.subLabelNew):T.followLabel;
  const right=isSub?('<span>'+tier.label+'</span><span class="chev">'+CHEV.repeat(tier.n)+'</span>'):'<span>Follow</span>';
  const line=isSub?(resub?T.subLineRe:T.subLineNew):T.followLine;
  const msg=(isSub&&o.message&&String(o.message).trim())?'<div class="msg">'+o.message+'</div>':'';
  el.innerHTML=
    '<div class="card">'+
      (isSub&&o.head!==false?'<div class="peek"><img src="'+o.assets.head+'" alt=""></div>':'')+
      '<div class="plate"><div class="tex"></div><div class="band"></div><div class="foot"></div></div>'+
      '<div class="badge"><img src="'+o.assets.badge+'" alt=""></div>'+
      '<div class="txt">'+
        '<div class="lbl"><span class="dot"></span><span class="lt"></span>'+
          '<span class="meter">'+'<i></i>'.repeat(6)+'</span><span class="right">'+right+'</span></div>'+
        '<div class="name"></div>'+
        '<div class="line">'+esc(line)+'</div>'+msg+
      '</div>'+
      (isSub?'<div class="stat"><div class="num">'+String(months).padStart(2,'0')+'</div><div class="unit">'+(months===1?'Month':'Months')+'</div></div>':'')+
      '<div class="scan"></div>'+
      '<div class="br tl"></div><div class="br tr"></div><div class="br bl"></div><div class="br brr"></div>'+
    '</div>';
  stage.appendChild(el);

  const q=s=>el.querySelector(s);
  const card=q('.card'), plate=q('.plate'), scan=q('.scan'), badge=q('.badge'),
        lt=q('.lt'), lbl=q('.lbl'), meter=[...el.querySelectorAll('.meter i')],
        nameEl=q('.name'), lineEl=q('.line'), msgEl=q('.msg'), stat=q('.stat'),
        numEl=q('.num'), peek=q('.peek img'), dot=q('.dot'),
        brs=[...el.querySelectorAll('.br')];

  // fit long names: measure at full size with the real text, then shrink
  nameEl.textContent=name;
  const maxW=isSub?820:900;
  const base=parseFloat(getComputedStyle(nameEl).fontSize);
  const w0=nameEl.scrollWidth;
  if(w0>maxW) nameEl.style.fontSize=(base*maxW/w0).toFixed(1)+'px';
  const nameW=nameEl.getBoundingClientRect().width;
  nameEl.style.width=Math.ceil(nameW)+'px';   // keeps the card still while letters decode
  const cw=card.offsetWidth, ch=card.offsetHeight;
  const labelText=label.toUpperCase();

  // timeline (ms). Sub is the same skeleton, half a beat slower and heavier.
  const k=isSub?1.12:1;
  const A={brIn:[0,380*k], scanIn:[220,900*k], badge:[380,700*k], label:[520,900*k],
           name:[640,1380*k], line:[1150,1450*k], stat:[1250,2150], peek:[1500,2050],
           nod:[2700,3300], sheen:[1500,2300],
           outTxt:[5000,5280], peekOut:[4850,5250], scanOut:[5200,5720], brOut:[5640,5980]};

  function render(t){
    if(t<0||t>DUR){ el.style.visibility='hidden'; return; }
    el.style.visibility='visible';

    // brackets: fly from centre to the corners, then collapse back on exit
    const bi=outExpo(seg(t,...A.brIn)), bo=inCubic(seg(t,...A.brOut));
    const bp=bi*(1-bo);
    const dx=(cw/2)*(1-bp), dy=(ch/2)*(1-bp);
    const bop=Math.min(seg(t,0,120),1-bo);
    const sgn=[[1,1],[-1,1],[1,-1],[-1,-1]];
    brs.forEach((b,i)=>{b.style.opacity=bop; b.style.transform='translate('+(sgn[i][0]*dx)+'px,'+(sgn[i][1]*dy)+'px)';});

    // plate opens behind a scan line, and closes behind it on the way out
    const si=inOut(seg(t,...A.scanIn)), so=inOut(seg(t,...A.scanOut));
    const open=si*(1-so);
    plate.style.clipPath='inset(0 '+((1-open)*100).toFixed(2)+'% 0 0)';
    const scanning=(t>A.scanIn[0]&&t<A.scanIn[1]+120)||(t>A.scanOut[0]-60&&t<A.scanOut[1]);
    scan.style.opacity=scanning?(t<3000?Math.min(1,seg(t,A.scanIn[0],A.scanIn[0]+80)*(1-seg(t,A.scanIn[1],A.scanIn[1]+120))):Math.min(seg(t,A.scanOut[0]-60,A.scanOut[0]),1-seg(t,A.scanOut[1]-80,A.scanOut[1]))):0;
    scan.style.left=(open*cw-1)+'px';

    const out=seg(t,...A.outTxt), outE=inCubic(out);
    const shift='translateX('+(-14*outE)+'px)';

    // badge flickers on like a screen catching signal
    const bpz=seg(t,...A.badge);
    const flick=bpz<=0?0:(bpz<.25?.9:bpz<.4?.25:bpz<.55?1:bpz<.65?.55:1);
    badge.style.opacity=flick*(1-outE);
    badge.style.transform='scale('+(.88+.12*outBack(bpz))+') '+shift;

    // label types itself out; the dot blinks like a carrier light
    const ln=Math.round(labelText.length*seg(t,...A.label));
    lt.textContent=labelText.slice(0,ln)+(ln<labelText.length&&t>A.label[0]?'_':'');
    lbl.style.opacity=(t<A.label[0]?0:1)*(1-outE);
    lbl.style.transform=shift;
    lbl.querySelector('.right').style.opacity=seg(t,A.label[1]-100,A.label[1]+200);
    dot.style.opacity=t<A.label[0]?0:(Math.floor(t/420)%2===0?1:.25);
    // radio meter: busy while the call comes in, settles to a low idle
    const busy=1-seg(t,2600,3400);
    meter.forEach((m,i)=>{
      const f=Math.floor(t/70);
      const busyH=3+15*rnd(f*7+i*13)*(.55+.45*Math.sin(i*.9+t/160));
      const idleH=3+4*rnd(Math.floor(t/240)*5+i);
      m.style.height=Math.max(3,(busyH*busy+idleH*(1-busy))).toFixed(1)+'px';
    });

    // name decodes left to right out of radio static
    const np=seg(t,...A.name);
    if(t<A.name[0]){ nameEl.textContent=' '; }
    else{
      const chars=[...name], n=chars.length, f=Math.floor(t/45);
      let s='';
      for(let i=0;i<n;i++){
        const lock=(i+1)/n;
        if(np>=lock||chars[i]===' ') s+=chars[i];
        else if(np>=lock-.35) s+=GLYPHS[Math.floor(rnd(f*31+i*17)*GLYPHS.length)];
        else s+=' ';
      }
      nameEl.textContent=s;
    }
    nameEl.style.opacity=1-outE;
    nameEl.style.transform=shift;
    if(isSub){ const sh=inOut(seg(t,...A.sheen)); nameEl.style.backgroundPosition=(100-100*sh)+'% 0'; }

    const lp=outCubic(seg(t,...A.line));
    lineEl.style.opacity=lp*(1-outE);
    lineEl.style.transform='translateY('+(10*(1-lp))+'px) '+shift;
    if(msgEl){ const mp=outCubic(seg(t,A.line[0]+250,A.line[1]+300)); msgEl.style.opacity=mp*(1-outE); msgEl.style.transform='translateY('+(10*(1-mp))+'px) '+shift; }

    if(stat){
      const sp=seg(t,...A.stat);
      stat.style.opacity=(t<A.stat[0]?0:1)*(1-outE);
      stat.style.transform=shift;
      const v=Math.max(1,Math.round(months*outCubic(sp)));
      numEl.textContent=String(t<A.stat[0]?0:v).padStart(2,'0');
    }

    if(peek){
      const pin=outBack(seg(t,...A.peek)), pout=inCubic(seg(t,...A.peekOut));
      const y=196-196*pin+196*pout;
      const nod=Math.sin(seg(t,...A.nod)*Math.PI*2)*2.2;
      peek.style.top=y.toFixed(1)+'px';
      peek.style.transform='rotate('+nod.toFixed(2)+'deg)';
      peek.style.transformOrigin='50% 90%';
    }
  }
  render(-1);
  return {el, duration:DUR, render};
}
global.createAlert=createAlert;
})(window);

/* StreamElements runner: SE writes the event into the hidden spans in the HTML
   tab before this runs; the alert plays once, then hides itself. */

(function(){
  var ASSETS={badge:'data:image/webp;base64,', head:'data:image/webp;base64,'};
  var TXT={followLabel:'New recruit',followLine:'has reported for duty.',subLabelNew:'Enlisted',subLabelRe:'Re-enlisted',subLineNew:'Signed on. Paperwork filed.',subLineRe:'Back for another tour.'};
  var stage=document.getElementById('stage');
  function build(d){return {type:d.type,name:d.name||'',months:d.months||'',tier:d.tier||'',message:d.message||'',text:TXT,head:true,assets:ASSETS};}
  function play(d){return new Promise(function(res){var a=createAlert(stage,build(d));var t0=performance.now();function tick(now){var t=now-t0;a.render(t);if(t<=a.duration+50){requestAnimationFrame(tick);}else{res();}}requestAnimationFrame(tick);});}
  var Q=[],busy=false;
  function pump(){if(busy||!Q.length)return;busy=true;var d=Q.shift();Promise.race([Promise.all([document.fonts.load('108px AboHv'),document.fonts.load('30px AboCond')]),new Promise(function(r){setTimeout(r,1500);})]).then(function(){return play(d);}).then(function(){setTimeout(function(){busy=false;pump();},500);});}
  function enqueue(d){Q.push(d);pump();}
  window.addEventListener('onEventReceived',function(obj){if(!obj||!obj.detail)return;var l=obj.detail.listener,ev=obj.detail.event||{};if(l==='follower-latest'){enqueue({type:'follow',name:ev.name});}else if(l==='subscriber-latest'){if(ev.gifted&&ev.isCommunityGift)return;enqueue({type:'sub',name:ev.name,months:ev.amount,tier:ev.tier,message:ev.message});}});
  window.addEventListener('onWidgetLoad',function(obj){try{var fd=(obj.detail&&obj.detail.fieldData)||{};if(fd.testOnLoad==='yes'){enqueue({type:'follow',name:'TESTNAME'});}}catch(e){}});
})();